114	/// Run the git program and wait for it. Progress lines from stderr are reported.
115	pub fn run_git(engine: &Engine, dir: &Path, args: &[&str], progress: Option<Progress>) -> GResult<String> {
116	    let git = engine.cli.as_ref().ok_or_else(|| "Git program not found".to_string())?;
117	    let mut cmd = quiet_command(git);
118	    cmd.args(args)
119	        .current_dir(dir)
120	        .env("GIT_TERMINAL_PROMPT", "0")
121	        .env("LC_ALL", "C")
122	        .stdin(Stdio::null())
123	        .stdout(Stdio::piped())
124	        .stderr(Stdio::piped());
125	    if !engine.user_name.is_empty() {
126	        cmd.env("GIT_AUTHOR_NAME", &engine.user_name).env("GIT_COMMITTER_NAME", &engine.user_name);
127	    }
128	    if !engine.user_email.is_empty() {
129	        cmd.env("GIT_AUTHOR_EMAIL", &engine.user_email).env("GIT_COMMITTER_EMAIL", &engine.user_email);
130	    }
131	    let mut child = cmd.spawn().map_err(|e| format!("cannot start git: {e}"))?;
132	    let mut stdout = child.stdout.take().unwrap();
133	    let out_thread = std::thread::spawn(move || {
134	        let mut s = Vec::new();
135	        let _ = stdout.read_to_end(&mut s);
136	        s
137	    });
138	    let mut stderr = child.stderr.take().unwrap();
139	    let mut err_all = Vec::new();
140	    let mut line = Vec::new();
141	    let mut buf = [0u8; 1024];
142	    let mut progress = progress;
143	    loop {
144	        let n = stderr.read(&mut buf).unwrap_or(0);
145	        if n == 0 {
146	            break;
147	        }
148	        for &b in &buf[..n] {
149	            err_all.push(b);
150	            if b == b'\r' || b == b'\n' {
151	                if let Some(p) = progress.as_mut() {
152	                    let l = String::from_utf8_lossy(&line).to_string();
153	                    if let Some(pct) = parse_percent(&l) {
154	                        p(pct, &l);
155	                    }
156	                }
157	                line.clear();
158	            } else {
159	                line.push(b);
160	            }
161	        }
162	    }
163	    let status = child.wait().map_err(|e| e.to_string())?;
164	    let out = out_thread.join().unwrap_or_default();
165	    let out_s = String::from_utf8_lossy(&out).to_string();
166	    let err_s = String::from_utf8_lossy(&err_all).to_string();
167	    if status.success() {
168	        let mut s = out_s;
169	        if s.trim().is_empty() {
170	            s = err_s.lines().filter(|l| !l.contains('%')).collect::<Vec<_>>().join("\n");
171	        }
172	        Ok(s.trim().to_string())
173	    } else {
174	        let msg = err_s
175	            .split(['\r', '\n'])
176	            .filter(|l| !l.trim().is_empty() && !l.contains('%'))
177	            .collect::<Vec<_>>()
178	            .join("\n");
179	        Err(if msg.is_empty() { out_s.trim().to_string() } else { msg })
180	    }
181	}
