183	fn parse_percent(l: &str) -> Option<f32> {
184	    let i = l.find('%')?;
185	    let start = l[..i].rfind(|c: char| !c.is_ascii_digit()).map(|x| x + 1).unwrap_or(0);
186	    let n: f32 = l[start..i].parse().ok()?;
187	    // Weight the phases of a clone/fetch so the bar keeps moving forward.
188	    let base = if l.starts_with("Receiving") {
189	        0.1
190	    } else if l.starts_with("Resolving") {
191	        0.8
192	    } else if l.starts_with("Updating files") || l.starts_with("Checking out") {
193	        0.9
194	    } else {
195	        0.0
196	    };
197	    let span = if base == 0.0 { 0.1 } else if base == 0.1 { 0.7 } else { 0.1 };
198	    Some(base + span * n / 100.0)
199	}
