201	fn callbacks<'a>(engine: &Engine, progress: Option<Progress<'a>>) -> RemoteCallbacks<'a> {
202	    let mut cb = RemoteCallbacks::new();
203	    let mut tries = 0;
204	    let gh = engine.token_github.clone();
205	    let gl = engine.token_gitlab.clone();
206	    cb.credentials(move |url, username, allowed| {
207	        tries += 1;
208	        if tries > 5 {
209	            return Err(git2::Error::from_str("authentication failed"));
210	        }
211	        if allowed.contains(CredentialType::SSH_KEY) {
212	            if tries <= 2 {
213	                return Cred::ssh_key_from_agent(username.unwrap_or("git"));
214	            }
215	            if let Some(home) = dirs::home_dir() {
216	                for k in ["id_ed25519", "id_rsa", "id_ecdsa"] {
217	                    let p = home.join(".ssh").join(k);
218	                    if p.exists() {
219	                        return Cred::ssh_key(username.unwrap_or("git"), None, &p, None);
220	                    }
221	                }
222	            }
223	        }
224	        if allowed.contains(CredentialType::USER_PASS_PLAINTEXT) {
225	            if url.contains("github") && !gh.is_empty() && tries <= 2 {
226	                return Cred::userpass_plaintext(username.unwrap_or("x-access-token"), &gh);
227	            }
228	            if url.contains("gitlab") && !gl.is_empty() && tries <= 2 {
229	                return Cred::userpass_plaintext("oauth2", &gl);
230	            }
231	            if let Ok(cfg) = git2::Config::open_default() {
232	                if let Ok(c) = Cred::credential_helper(&cfg, url, username) {
233	                    return Ok(c);
234	                }
235	            }
236	        }
237	        if allowed.contains(CredentialType::DEFAULT) {
238	            return Cred::default();
239	        }
240	        Err(git2::Error::from_str("no credentials available (add a token in Preferences or install Git)"))
241	    });
242	    if let Some(p) = progress {
243	        cb.transfer_progress(move |s| {
244	            let total = s.total_objects().max(1) as f32;
245	            let frac = (s.received_objects() as f32 / total) * 0.8 + (s.indexed_deltas() as f32 / s.total_deltas().max(1) as f32) * 0.2;
246	            p(frac, &format!("{}/{} objects", s.received_objects(), s.total_objects()));
247	            true
248	        });
249	    }
250	    cb
251	}
