        .unwrap_or_else(|| "gitcerberocraft-cli".into());
    let repo = app
        .active_repo_id()
        .and_then(|id| app.tabs.iter().find(|t| t.id == id))
        .and_then(|t| match &t.kind {
            TabKind::Repo(r) => Some(r.path.display().to_string()),
            _ => None,
        })

